using System; using System.Drawing; using System.Linq; using System.Windows.Forms; using AshkanLMS.Core; using AshkanLMS.Services;
namespace AshkanLMS.UI { public class MainForm:Form { readonly DataService data; Panel content,nav,top; Label pageTitle,who; string current="Dashboard"; readonly string[] menuKeys={"Dashboard","GlobalSearch","Students","Student360","RiskCenter","Courses","Course360","Instructors","InstructorWorkspace","Enrollments","Attendance","Assignments","Exams","Grades","Certificates","Calendar","Notifications","Reports","SecurityCenter","Users","Audit","Settings"}; public MainForm(DataService d){data=d;WindowState=FormWindowState.Maximized;MinimumSize=new Size(1100,700);BackColor=Theme.Canvas;Font=Theme.Font();BuildShell();Navigate("Dashboard");}
void BuildShell(){Controls.Clear();Localization.Direction(this);Text="AshkanLMS • "+Localization.T("Dashboard");nav=new Panel{Dock=DockStyle.None,Anchor=AnchorStyles.Top|AnchorStyles.Bottom,Width=245,BackColor=Theme.Navy,Padding=new Padding(12),RightToLeft=RightToLeft.No};Controls.Add(nav);var logo=new Label{Text="  A   AshkanLMS",Dock=DockStyle.Top,Height=75,ForeColor=Color.White,Font=Theme.Font(16,FontStyle.Bold),TextAlign=AppSession.Persian?ContentAlignment.MiddleRight:ContentAlignment.MiddleLeft,RightToLeft=RightToLeft.No};nav.Controls.Add(logo);for(int i=menuKeys.Length-1;i>=0;i--){string key=menuKeys[i];if(AppSession.Role=="Instructor"&&(key=="Users"||key=="SecurityCenter"||key=="Audit"))continue;var b=new Button{Text=(AppSession.Persian?Localization.T(key)+"   ":"   "+Localization.T(key)),Dock=DockStyle.Top,Height=42,FlatStyle=FlatStyle.Flat,ForeColor=Color.FromArgb(218,225,237),BackColor=Theme.Navy,TextAlign=AppSession.Persian?ContentAlignment.MiddleRight:ContentAlignment.MiddleLeft,Font=Theme.Font(9.5f),Cursor=Cursors.Hand,Tag=key};b.FlatAppearance.BorderSize=0;b.FlatAppearance.MouseOverBackColor=Theme.NavHover;b.Click+=(s,e)=>Navigate((string)((Button)s).Tag);nav.Controls.Add(b);}top=new Panel{Dock=DockStyle.None,Height=68,BackColor=Theme.Header,Padding=new Padding(22,10,22,10),RightToLeft=AppSession.Persian?RightToLeft.Yes:RightToLeft.No};Controls.Add(top);pageTitle=Theme.Label(Localization.T(current),17,FontStyle.Bold);pageTitle.Location=new Point(22,20);top.Controls.Add(pageTitle);who=Theme.Label(AppSession.UserName+"  •  "+AppSession.Role,9,FontStyle.Bold);who.ForeColor=Theme.Muted;who.AutoSize=true;top.Controls.Add(who);var lang=Theme.Button(Localization.T("Language"));lang.Size=new Size(100,34);lang.Anchor=AnchorStyles.Top|AnchorStyles.Right;lang.Click+=(s,e)=>{Localization.Set(!AppSession.Persian);BuildShell();Navigate(current);};top.Controls.Add(lang);top.Resize+=(s,e)=>{if(AppSession.Persian){who.Left=22;lang.Left=top.Width-120;}else{lang.Left=top.Width-120;who.Left=Math.Max(130,top.Width-who.Width-250);}who.Top=24;lang.Top=17;};content=new BackgroundPanel{Dock=DockStyle.None,Anchor=AnchorStyles.Top|AnchorStyles.Bottom|AnchorStyles.Left|AnchorStyles.Right,BackColor=Theme.Canvas,ImagePath=Theme.BackgroundImagePath,OverlayColor=Color.FromArgb(118,12,25,48),AutoScroll=true,Padding=new Padding(24)};Controls.Add(content);content.BringToFront();top.BringToFront();nav.BringToFront();top.PerformLayout();LayoutDirectionManager.Apply(this);Resize+=delegate{ApplyShellBounds();};ApplyShellBounds();}
void ApplyShellBounds(){
if(nav==null||top==null||content==null)return;
int nw=245; int cw=ClientSize.Width; int ch=ClientSize.Height;
// IMPORTANT: MainForm.RightToLeftLayout stays false. These are physical coordinates.
if(AppSession.Persian){
 nav.SetBounds(Math.Max(0,cw-nw),0,nw,ch);
 top.SetBounds(0,0,Math.Max(0,cw-nw),68);
 content.SetBounds(0,68,Math.Max(0,cw-nw),Math.Max(0,ch-68));
}else{
 nav.SetBounds(0,0,nw,ch);
 top.SetBounds(nw,0,Math.Max(0,cw-nw),68);
 content.SetBounds(nw,68,Math.Max(0,cw-nw),Math.Max(0,ch-68));
}
nav.BringToFront(); top.BringToFront();
}
void Navigate(string key){current=key;pageTitle.Text=Localization.T(key);foreach(Control c in nav.Controls)if(c is Button){var mb=(Button)c;mb.BackColor=(mb.Tag as string)==key?Theme.NavActive:Theme.Navy;}if(key=="Dashboard")ShowDashboard();else if(key=="Students")ShowStudents();else if(key=="Courses")ShowCourses();else if(key=="Audit")ShowAudit();else if(key=="Student360")ShowStudent360();else if(key=="Calendar")ShowCalendar();else if(key=="Notifications")ShowNotifications();else if(key=="GlobalSearch")ShowGlobalSearch();else if(key=="RiskCenter")ShowRiskCenter();else if(key=="Course360")ShowCourse360();else if(key=="InstructorWorkspace")ShowInstructorWorkspace();else if(key=="Reports")ShowReports();else if(key=="SecurityCenter")ShowSecurityCenter();else if(key=="Instructors")ShowOperational(key,data.Instructors,new[]{"Id","Name","Expertise","Email","CourseCount"});else if(key=="Enrollments")ShowOperational(key,data.Enrollments,new[]{"Id","Student","Course","Date","Status"});else if(key=="Attendance")ShowOperational(key,data.Attendance,new[]{"Id","Student","Course","Date","Status"});else if(key=="Assignments")ShowOperational(key,data.Assignments,new[]{"Id","Title","Course","DueDate","Submitted","Status"});else if(key=="Exams")ShowOperational(key,data.Exams,new[]{"Id","Title","Course","Date","Questions","Status"});else if(key=="Grades")ShowOperational(key,data.Grades,new[]{"Id","Student","Course","Score","Letter"});else if(key=="Certificates")ShowOperational(key,data.Certificates,new[]{"Id","Student","Course","IssuedAt","Code"});else ShowModule(key);LayoutDirectionManager.ApplyTo(content);}void Clear(){content.Controls.Clear();}Panel Card(int x,int y,int w,int h){var p=new ModernCard{Location=new Point(x,y),Size=new Size(w,h),BackColor=Theme.Card,Padding=new Padding(18),RightToLeft=AppSession.Persian?RightToLeft.Yes:RightToLeft.No};content.Controls.Add(p);return p;}Label Header(string s){var l=Theme.Label(s,13,FontStyle.Bold);l.Location=new Point(18,18);return l;}DataGridView Grid(){var g=new DataGridView{BackgroundColor=Theme.Card,BorderStyle=BorderStyle.None,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,AllowUserToAddRows=false,AllowUserToDeleteRows=false,ReadOnly=true,RowHeadersVisible=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,Font=Theme.Font(9),ColumnHeadersHeight=36};g.RowTemplate.Height=34;g.RightToLeft=AppSession.Persian?RightToLeft.Yes:RightToLeft.No;g.ColumnHeadersDefaultCellStyle.Alignment=AppSession.Persian?DataGridViewContentAlignment.MiddleRight:DataGridViewContentAlignment.MiddleLeft;g.DefaultCellStyle.Alignment=AppSession.Persian?DataGridViewContentAlignment.MiddleRight:DataGridViewContentAlignment.MiddleLeft;return g;}
void ShowDashboard(){Clear();var metrics=new[]{Tuple.Create(Localization.T("ActiveStudents"),"126","+12%"),Tuple.Create(Localization.T("ActiveCourses"),"12","+2"),Tuple.Create(Localization.T("Completion"),"74%","+5%"),Tuple.Create(Localization.T("PendingExams"),"8",Localization.T("Today"))};int x=24;foreach(var m in metrics){var c=Card(x,24,210,118);var l=Theme.Label(m.Item1,9,FontStyle.Bold);l.ForeColor=Theme.Muted;l.Location=new Point(18,18);c.Controls.Add(l);var v=Theme.Label(m.Item2,24,FontStyle.Bold);v.Location=new Point(18,48);c.Controls.Add(v);var s=Theme.Label(m.Item3,9,FontStyle.Bold);s.ForeColor=Theme.Green;s.Location=new Point(135,78);c.Controls.Add(s);x+=226;}var courses=Card(24,160,660,370);courses.Controls.Add(Header(Localization.T("RunningCourses")));var grid=Grid();grid.Location=new Point(18,60);grid.Size=new Size(624,285);grid.DataSource=data.Courses.Select(c=>new CourseRow{ID=c.Id,Title=c.Title,Instructor=c.Instructor,Students=c.Students,Progress=c.Progress+"%",Status=Localization.T(c.StatusKey)}).ToList();LocalizeCourseGrid(grid);courses.Controls.Add(grid);var activity=Card(700,160,310,370);activity.Controls.Add(Header(Localization.T("RecentActivity")));int y=65;foreach(var a in data.Activities){var t=Theme.Label(Localization.T(a.TypeKey),9,FontStyle.Bold);t.ForeColor=Theme.Blue;t.Location=new Point(18,y);activity.Controls.Add(t);var tx=Theme.Label(Localization.T(a.TextKey),8.5f);tx.MaximumSize=new Size(260,0);tx.Location=new Point(18,y+24);activity.Controls.Add(tx);var tm=Theme.Label(a.At.ToString("HH:mm"),8);tm.ForeColor=Theme.Muted;tm.Location=new Point(230,y);activity.Controls.Add(tm);y+=82;}}
void ShowStudents(){Clear();var c=Card(24,24,986,530);c.Controls.Add(Header(Localization.T("StudentManagement")));var add=Theme.Button(Localization.T("NewStudent"));add.Location=new Point(790,14);add.Width=170;add.Click+=(s,e)=>AddStudent();c.Controls.Add(add);var g=Grid();g.Location=new Point(18,70);g.Size=new Size(950,420);g.DataSource=data.Students.Select(s=>new StudentRow{ID=s.Id,Name=s.Name,Email=s.Email,Progress=s.Progress+"%",Status=Localization.T(s.StatusKey)}).ToList();SetHeaders(g,new[]{"Id","Name","Email","Progress","Status"});c.Controls.Add(g);}void ShowCourses(){Clear();var c=Card(24,24,986,530);c.Controls.Add(Header(Localization.T("CourseManagement")));var add=Theme.Button(Localization.T("NewCourse"));add.Location=new Point(800,14);add.Width=160;add.Click+=(s,e)=>AddCourse();c.Controls.Add(add);var g=Grid();g.Location=new Point(18,70);g.Size=new Size(950,420);g.DataSource=data.Courses.Select(s=>new CourseRow{ID=s.Id,Title=s.Title,Instructor=s.Instructor,Students=s.Students,Progress=s.Progress+"%",Status=Localization.T(s.StatusKey)}).ToList();LocalizeCourseGrid(g);c.Controls.Add(g);}void ShowOperational(string key,object source,string[] headers){Clear();var c=Card(24,24,986,530);c.Controls.Add(Header(Localization.T(key)+" • "+Localization.T("OperationalModule")));var g=Grid();g.Location=new Point(18,70);g.Size=new Size(950,420);g.DataSource=source;SetHeaders(g,headers);TranslateStatusCells(g);c.Controls.Add(g);}void TranslateStatusCells(DataGridView g){if(!g.Columns.Contains("StatusKey"))return;g.Columns["StatusKey"].HeaderText=Localization.T("Status");foreach(DataGridViewRow r in g.Rows)if(r.Cells["StatusKey"].Value!=null)r.Cells["StatusKey"].Value=Localization.T(r.Cells["StatusKey"].Value.ToString());}void ShowAudit(){Clear();var c=Card(24,24,986,530);c.Controls.Add(Header(Localization.T("Audit")));var g=Grid();g.Location=new Point(18,70);g.Size=new Size(950,420);g.DataSource=data.Audit.Select(a=>new{Time=a.At,User=a.User,Action=Localization.T(a.ActionKey),Entity=a.Entity}).ToList();SetHeaders(g,new[]{"Time","User","Action","Entity"});c.Controls.Add(g);}void AddStudent(){using(var f=new Form{Text=Localization.T("NewStudent"),StartPosition=FormStartPosition.CenterParent,Size=new Size(420,250),Font=Theme.Font(),BackColor=Theme.Canvas}){Localization.Direction(f);var n=new TextBox{Left=30,Top=45,Width=340};var e=new TextBox{Left=30,Top=105,Width=340};var nl=Theme.Label(Localization.T("Name"),9,FontStyle.Bold);nl.Location=new Point(30,22);var el=Theme.Label(Localization.T("Email"),9,FontStyle.Bold);el.Location=new Point(30,82);var b=Theme.Button(Localization.T("NewStudent"));b.Location=new Point(230,155);b.Width=140;b.Click+=(x,y)=>{if(n.Text.Trim().Length<2||!e.Text.Contains("@")){MessageBox.Show(Localization.T("Validation"));return;}data.AddStudent(n.Text.Trim(),e.Text.Trim());f.DialogResult=DialogResult.OK;};f.Controls.AddRange(new Control[]{nl,n,el,e,b});LayoutDirectionManager.Apply(f);if(f.ShowDialog(this)==DialogResult.OK)ShowStudents();}}void AddCourse(){using(var f=new Form{Text=Localization.T("NewCourse"),StartPosition=FormStartPosition.CenterParent,Size=new Size(420,250),Font=Theme.Font(),BackColor=Theme.Canvas}){Localization.Direction(f);var n=new TextBox{Left=30,Top=45,Width=340};var i=new TextBox{Left=30,Top=105,Width=340};var nl=Theme.Label(Localization.T("Title"),9,FontStyle.Bold);nl.Location=new Point(30,22);var il=Theme.Label(Localization.T("Instructor"),9,FontStyle.Bold);il.Location=new Point(30,82);var b=Theme.Button(Localization.T("NewCourse"));b.Location=new Point(230,155);b.Width=140;b.Click+=(x,y)=>{if(n.Text.Trim().Length<2||i.Text.Trim().Length<2){MessageBox.Show(Localization.T("Validation"));return;}data.AddCourse(n.Text.Trim(),i.Text.Trim());f.DialogResult=DialogResult.OK;};f.Controls.AddRange(new Control[]{nl,n,il,i,b});LayoutDirectionManager.Apply(f);if(f.ShowDialog(this)==DialogResult.OK)ShowCourses();}}void ShowModule(string key){Clear();var c=Card(24,24,986,450);c.Controls.Add(Header(Localization.T(key)));var desc=Theme.Label(Localization.T("ModuleDesc"),10);desc.ForeColor=Theme.Muted;desc.Location=new Point(18,70);desc.MaximumSize=new Size(900,0);c.Controls.Add(desc);var features=new[]{"AdvancedSearch","Export","RBAC","Validation","AuditReady","Responsive"};int y=125;foreach(var f in features){var l=Theme.Label("✓  "+Localization.T(f),10,FontStyle.Bold);l.ForeColor=Theme.Text;l.Location=new Point(25,y);c.Controls.Add(l);y+=42;}}

void ShowStudent360(){Clear();var c=Card(24,24,986,570);c.Controls.Add(Header(Localization.T("Student360")));var search=new TextBox{Location=new Point(18,62),Width=360,Font=Theme.Font(10)};search.Text=data.Students.First().Name;c.Controls.Add(search);var b=Theme.Button(Localization.T("OpenProfile"));b.Location=new Point(390,58);b.Width=150;c.Controls.Add(b);var info=Theme.Label("",11,FontStyle.Bold);info.Location=new Point(18,120);info.MaximumSize=new Size(900,0);c.Controls.Add(info);var g=Grid();g.Location=new Point(18,205);g.Size=new Size(950,320);c.Controls.Add(g);Action refresh=()=>{var st=data.Students.FirstOrDefault(x=>x.Name.IndexOf(search.Text.Trim(),StringComparison.OrdinalIgnoreCase)>=0);if(st==null)st=data.Students.First();info.Text=Localization.T("Student")+": "+st.Name+"     "+Localization.T("Email")+": "+st.Email+"     "+Localization.T("Progress")+": "+st.Progress+"%";g.DataSource=data.Enrollments.Where(x=>x.Student==st.Name).Select(x=>new{Course=x.Course,Date=x.Date,Status=Localization.T(x.StatusKey)}).ToList();SetHeaders(g,new[]{"Course","Date","Status"});};b.Click+=(s,e)=>refresh();refresh();}
void ShowCalendar(){Clear();var c=Card(24,24,986,570);c.Controls.Add(Header(Localization.T("Calendar")));var cal=new MonthCalendar{Location=new Point(24,70),MaxSelectionCount=1};c.Controls.Add(cal);var g=Grid();g.Location=new Point(300,70);g.Size=new Size(650,440);g.DataSource=data.Exams.OrderBy(x=>x.Date).Select(x=>new{Title=x.Title,Course=x.Course,Date=x.Date,Status=Localization.T(x.StatusKey)}).ToList();SetHeaders(g,new[]{"Title","Course","Date","Status"});c.Controls.Add(g);}
void ShowNotifications(){Clear();var c=Card(24,24,986,570);c.Controls.Add(Header(Localization.T("NotificationCenter")));int y=70;foreach(var a in data.Activities){var n=new ModernCard{Location=new Point(18,y),Size=new Size(930,90),BackColor=Theme.Card,Padding=new Padding(16)};var t=Theme.Label(Localization.T(a.TypeKey),10,FontStyle.Bold);t.ForeColor=Theme.Blue;t.Location=new Point(16,14);n.Controls.Add(t);var d=Theme.Label(Localization.T(a.TextKey),9);d.Location=new Point(16,43);d.MaximumSize=new Size(760,0);n.Controls.Add(d);var tm=Theme.Label(a.At.ToString("g"),8);tm.ForeColor=Theme.Muted;tm.Location=new Point(780,16);n.Controls.Add(tm);c.Controls.Add(n);y+=100;}}
void ShowGlobalSearch(){Clear();var c=Card(24,24,986,570);c.Controls.Add(Header(Localization.T("GlobalSearch")));var q=new TextBox{Location=new Point(18,62),Width=520,Font=Theme.Font(10)};c.Controls.Add(q);var g=Grid();g.Location=new Point(18,115);g.Size=new Size(950,410);c.Controls.Add(g);Action run=()=>{string term=q.Text.Trim();var rows=new System.Collections.Generic.List<SearchRow>();foreach(var st in data.Students.Where(x=>term.Length==0||x.Name.IndexOf(term,StringComparison.OrdinalIgnoreCase)>=0||x.Email.IndexOf(term,StringComparison.OrdinalIgnoreCase)>=0))rows.Add(new SearchRow{Type=Localization.T("Student"),Title=st.Name,Details=st.Email,Status=Localization.T(st.StatusKey)});foreach(var co in data.Courses.Where(x=>term.Length==0||x.Title.IndexOf(term,StringComparison.OrdinalIgnoreCase)>=0||x.Instructor.IndexOf(term,StringComparison.OrdinalIgnoreCase)>=0))rows.Add(new SearchRow{Type=Localization.T("Course"),Title=co.Title,Details=co.Instructor,Status=Localization.T(co.StatusKey)});foreach(var ins in data.Instructors.Where(x=>term.Length==0||x.Name.IndexOf(term,StringComparison.OrdinalIgnoreCase)>=0||x.Expertise.IndexOf(term,StringComparison.OrdinalIgnoreCase)>=0))rows.Add(new SearchRow{Type=Localization.T("Instructor"),Title=ins.Name,Details=ins.Expertise,Status=Localization.T("Active")});g.DataSource=rows;};q.TextChanged+=(s,e)=>run();run();}
void ShowRiskCenter(){Clear();var c=Card(24,24,986,570);c.Controls.Add(Header(Localization.T("RiskCenter")));var g=Grid();g.Location=new Point(18,70);g.Size=new Size(950,455);g.DataSource=data.Students.OrderBy(x=>x.Progress).Select(x=>new RiskRow{Student=x.Name,Progress=x.Progress+"%",Risk=x.Progress<50?Localization.T("AtRisk"):Localization.T("Healthy"),Status=Localization.T(x.StatusKey)}).ToList();SetHeaders(g,new[]{"Student","Progress","Status","Status"});c.Controls.Add(g);}
void ShowCourse360(){Clear();var c=Card(24,24,986,570);c.Controls.Add(Header(Localization.T("Course360")));var combo=new ComboBox{Location=new Point(18,62),Width=420,DropDownStyle=ComboBoxStyle.DropDownList,Font=Theme.Font(10)};combo.DataSource=data.Courses.Select(x=>x.Title).ToList();c.Controls.Add(combo);var info=Theme.Label("",11,FontStyle.Bold);info.Location=new Point(18,115);info.MaximumSize=new Size(920,0);c.Controls.Add(info);var g=Grid();g.Location=new Point(18,180);g.Size=new Size(950,345);c.Controls.Add(g);Action refresh=()=>{var co=data.Courses.First(x=>x.Title==combo.SelectedItem.ToString());info.Text=Localization.T("Instructor")+": "+co.Instructor+"     "+Localization.T("StudentCount")+": "+co.Students+"     "+Localization.T("Progress")+": "+co.Progress+"%";g.DataSource=data.Enrollments.Where(x=>x.Course==co.Title).Select(x=>new{Student=x.Student,Date=x.Date,Status=Localization.T(x.StatusKey)}).ToList();SetHeaders(g,new[]{"Student","Date","Status"});};combo.SelectedIndexChanged+=(s,e)=>refresh();refresh();}
void ShowInstructorWorkspace(){Clear();var c=Card(24,24,986,570);c.Controls.Add(Header(Localization.T("InstructorWorkspace")));var g=Grid();g.Location=new Point(18,70);g.Size=new Size(950,455);g.DataSource=data.Instructors.Select(x=>new InstructorRow{Name=x.Name,Expertise=x.Expertise,Email=x.Email,Courses=x.Courses}).ToList();SetHeaders(g,new[]{"Name","Expertise","Email","CourseCount"});c.Controls.Add(g);}
void ShowReports(){Clear();var c=Card(24,24,986,570);c.Controls.Add(Header(Localization.T("ReportCenter")));var avg=data.Grades.Count==0?0:data.Grades.Average(x=>x.Score);var insights=Theme.Label(Localization.T("QuickInsights")+"\n\n"+Localization.T("ActiveStudents")+": "+data.Students.Count+"\n"+Localization.T("ActiveCourses")+": "+data.Courses.Count+"\n"+Localization.T("AverageScore")+": "+avg.ToString("0.00")+"\n"+Localization.T("UpcomingExams")+": "+data.Exams.Count(x=>x.Date>=DateTime.Today),12,FontStyle.Bold);insights.Location=new Point(24,75);insights.MaximumSize=new Size(500,0);c.Controls.Add(insights);var b=Theme.Button(Localization.T("ExportCsv"));b.Location=new Point(760,70);b.Width=180;b.Click+=(s,e)=>ExportStudentsCsv();c.Controls.Add(b);var g=Grid();g.Location=new Point(18,230);g.Size=new Size(950,295);g.DataSource=data.Students.Select(x=>new StudentRow{ID=x.Id,Name=x.Name,Email=x.Email,Progress=x.Progress+"%",Status=Localization.T(x.StatusKey)}).ToList();SetHeaders(g,new[]{"Id","Name","Email","Progress","Status"});c.Controls.Add(g);}
void ExportStudentsCsv(){using(var d=new SaveFileDialog{Filter="CSV (*.csv)|*.csv",FileName="AshkanLMS-students.csv"}){if(d.ShowDialog(this)!=DialogResult.OK)return;var lines=new System.Collections.Generic.List<string>();lines.Add("ID,Name,Email,Progress,Status");foreach(var x in data.Students)lines.Add(x.Id+",\""+x.Name.Replace("\"","\"\"")+"\",\""+x.Email+"\","+x.Progress+",\""+Localization.T(x.StatusKey)+"\"");System.IO.File.WriteAllLines(d.FileName,lines,new System.Text.UTF8Encoding(true));data.Log("Created","CSV Report");MessageBox.Show(Localization.T("ExportCsv"));}}
void ShowSecurityCenter(){Clear();var c=Card(24,24,986,570);c.Controls.Add(Header(Localization.T("SecurityCenter")));var role=Theme.Label(Localization.T("RoleAware")+"\n\n"+Localization.T("User")+": "+AppSession.UserName+"\nRole: "+AppSession.Role+"\n\n✓ "+Localization.T("RBAC")+"\n✓ "+Localization.T("AuditReady")+"\n✓ "+Localization.T("Validation"),12,FontStyle.Bold);role.Location=new Point(24,80);role.MaximumSize=new Size(900,0);c.Controls.Add(role);}
void SetHeaders(DataGridView g,string[] keys){for(int i=0;i<keys.Length&&i<g.Columns.Count;i++)g.Columns[i].HeaderText=Localization.T(keys[i]);}void LocalizeCourseGrid(DataGridView g){SetHeaders(g,new[]{"Id","Title","Instructor","StudentCount","Progress","Status"});}string TranslateStatus(string s){if(AppSession.Persian)return s;if(s=="فعال")return "Active";if(s=="پیش‌نویس")return "Draft";if(s=="نیازمند پیگیری")return "Needs follow-up";return s;}string ActivityType(string s){if(s=="ثبت‌نام")return "Enrollment";if(s=="آزمون")return "Exam";if(s=="گواهی")return "Certificate";return s;}string ActivityText(string type){if(type=="ثبت‌نام")return "A new student joined C# & .NET.";if(type=="آزمون")return "The Clean Code exam was published.";if(type=="گواهی")return "3 course certificates were issued.";return type;}
class SearchRow{public string Type{get;set;}public string Title{get;set;}public string Details{get;set;}public string Status{get;set;}}class RiskRow{public string Student{get;set;}public string Progress{get;set;}public string Risk{get;set;}public string Status{get;set;}}class InstructorRow{public string Name{get;set;}public string Expertise{get;set;}public string Email{get;set;}public int Courses{get;set;}}class StudentRow{public int ID{get;set;}public string Name{get;set;}public string Email{get;set;}public string Progress{get;set;}public string Status{get;set;}}class CourseRow{public int ID{get;set;}public string Title{get;set;}public string Instructor{get;set;}public int Students{get;set;}public string Progress{get;set;}public string Status{get;set;}}
}}
